    val requestBodyChannel = when {
        message is LastHttpContent && !message.content().isReadable -> null

        message.method() === HttpMethod.GET &&
            !HttpUtil.isContentLengthSet(message) &&
            !HttpUtil.isTransferEncodingChunked(message) -> {
