```javascript
/** Walk the prototype chain (excluding the source realm's Object.prototype) looking for an own `prop`. This distinguishes genuine own/inherited members — including class accessors and template prototypes — from members injected via Object.prototype pollution (e.g. `Object.prototype.username = '...'`), which live on Object.prototype itself and are therefore never matched. */
const hasOwnInPrototypeChain = (thing, prop) => {
  let obj = thing;
  const seen = [];

  while (obj != null) {
    if (seen.indexOf(obj) !== -1) {
      return false;
    }
    seen.push(obj);

    const prototype = getPrototypeOf(obj);

    if (isPrototypeBoundary(obj, prototype, obj === thing)) {
      return false;
    }

    if (hasOwnProperty(obj, prop)) {
      return true;
    }
    obj = prototype;
  }
  return false;
}
