function getTrailingIndentionLength(text) {
  let length = 0;

  for (let index = text.length - 1; index >= 0; index--) {
    const character = text[index];

    if (character === " " || character === "\t") {
      length++;
    } else {
      break;
    }
  }

  return length;
}
